#!/usr/bin/env python3
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
part = ROOT / 'template_parts' / 'part04.html'
text = part.read_text(encoding='utf-8')

old_api = "function seasonApiPlayers(s){return (DATA.seasonStats?.seasons?.[s]?.players||[]).map(p=>({name:p.name,team:p.team,m:+p.matches||0,g:+p.goals||0,a:+p.assists||0,pk:+p.penalties||0}))}"
new_api = "function seasonApiPlayers(s){return (DATA.seasonStats?.seasons?.[s]?.players||[]).map(p=>({name:p.name,team:p.team,m:+p.matches||0,g:+p.goals||0,a:0,pk:+p.penalties||0}))}\nfunction seasonApiAssists(s){return (DATA.seasonStats?.seasons?.[s]?.assists||[]).map(p=>({name:p.name,team:p.team,m:+p.matches||0,g:0,a:+p.assists||0,pk:0}))}"
if old_api not in text:
    raise SystemExit('seasonApiPlayers marker not found')
text = text.replace(old_api, new_api, 1)

start = text.index('function playerLeaderTable(')
end = text.index('\nfunction teamLeaderTable(', start)
new_table = '''function playerLeaderTable(rows,key,label){const sorted=[...rows].sort((a,b)=>b[key]-a[key]||a.name.localeCompare(b.name)).slice(0,10);if(!sorted.length)return '<div class="empty">Player leaderboard unavailable for this season.</div>';const showApps=sorted.some(p=>p.m>0);let last=null,rank=0;const ranked=sorted.map((p,i)=>{if(i===0||p[key]!==last)rank=i+1;last=p[key];return {...p,_rank:rank}});return `<div class="table"><table><thead><tr><th>#</th><th>Player</th><th>Club</th>${showApps?'<th>Apps</th>':''}<th>${label}</th></tr></thead><tbody>${ranked.map(p=>`<tr><td>${p._rank}</td><td class="team">${esc(p.name)}</td><td>${esc(p.team)}</td>${showApps?`<td>${p.m||'—'}</td>`:''}<td><b>${p[key]}</b></td></tr>`).join('')}</tbody></table></div>`}'''
text = text[:start] + new_table + text[end:]

start = text.index('function renderSeasonStats(){')
end = text.index('\n\nfunction renderPredictions()', start)
new_render = '''function renderSeasonStats(){const s=state.season,teams=seasonStatTeams(s),api=seasonApiPlayers(s),legacy=seasonLegacyScorers(s),scorers=api.length?api:legacy,assists=seasonApiAssists(s),maxGoals=scorers.length?Math.max(...scorers.map(x=>x.g)):0,maxAssists=assists.length?Math.max(...assists.map(x=>x.a)):0,scorerLeaders=maxGoals?scorers.filter(x=>x.g===maxGoals).sort((a,b)=>a.name.localeCompare(b.name)):[],assistLeaders=maxAssists?assists.filter(x=>x.a===maxAssists).sort((a,b)=>a.name.localeCompare(b.name)):[],leaderText=xs=>xs.length<=2?xs.map(x=>x.name).join(' · '):`${xs.length} players tied`,leaderTeams=xs=>xs.length===1?xs[0].team:(xs.length?'Joint leaders':''),cs=[...teams].sort((a,b)=>b.cs-a.cs||a.ga-b.ga)[0],attack=[...teams].sort((a,b)=>b.gf-a.gf||b.gd-a.gd)[0],defence=[...teams].sort((a,b)=>a.ga-b.ga||b.gd-a.gd)[0],wins=[...teams].sort((a,b)=>b.w-a.w||b.gd-a.gd)[0],hasCards=teams.some(x=>x.y||x.r),seasonFeed=DATA.seasonStats?.seasons?.[s]||{},coverage=api.length||assists.length?`Goals: football-data.org goal ranking · Assists: dedicated assist ranking`:(legacy.length?'Goals: archived scorer snapshot · assists unavailable':'Player leaderboards unavailable for this season');$('#stats').innerHTML=`<div class="toolbar"><div><div class="eyebrow">SEASON STATS</div><h2 class="title">${esc(s)} leaders</h2></div><div class="muted">${esc(coverage)}</div></div><div class="grid g6" style="margin-bottom:13px"><div class="card kpi"><span>Top scorer${scorerLeaders.length>1?'s':''}</span><b style="font-size:18px">${scorerLeaders.length?esc(leaderText(scorerLeaders)):'—'}</b><div class="muted">${scorerLeaders.length?`${maxGoals} goals · ${esc(leaderTeams(scorerLeaders))}`:'No player data'}</div></div><div class="card kpi"><span>Assist leader${assistLeaders.length>1?'s':''}</span><b style="font-size:18px">${assistLeaders.length?esc(leaderText(assistLeaders)):'—'}</b><div class="muted">${assistLeaders.length?`${maxAssists} assists · ${esc(leaderTeams(assistLeaders))}`:'No reliable assist feed'}</div></div><div class="card kpi"><span>Club clean sheets</span><b style="font-size:18px">${cs?esc(cs.team):'—'}</b><div class="muted">${cs?`${cs.cs} clean sheets`:'No matches'}</div></div><div class="card kpi"><span>Best attack</span><b style="font-size:18px">${attack?esc(attack.team):'—'}</b><div class="muted">${attack?`${attack.gf} goals`:'No matches'}</div></div><div class="card kpi"><span>Best defence</span><b style="font-size:18px">${defence?esc(defence.team):'—'}</b><div class="muted">${defence?`${defence.ga} conceded`:'No matches'}</div></div><div class="card kpi"><span>Most wins</span><b style="font-size:18px">${wins?esc(wins.team):'—'}</b><div class="muted">${wins?`${wins.w} wins`:'No matches'}</div></div></div><div class="grid g2" style="margin-bottom:13px"><div class="card"><div class="eyebrow">TOP GOAL SCORERS</div><div style="margin-top:10px">${playerLeaderTable(scorers,'g','Goals')}</div></div><div class="card"><div class="eyebrow">TOP ASSISTS</div><div style="margin-top:10px">${playerLeaderTable(assists,'a','Assists')}</div></div></div><div class="grid g2"><div class="card"><div class="eyebrow">CLUB CLEAN SHEETS</div><div style="margin-top:10px">${teamLeaderTable(teams,'cs','CS')}</div></div><div class="card"><div class="eyebrow">BEST ATTACKS</div><div style="margin-top:10px">${teamLeaderTable(teams,'gf','Goals')}</div></div></div>${hasCards?`<div class="grid g2" style="margin-top:13px"><div class="card"><div class="eyebrow">YELLOW CARDS · TEAM</div><div style="margin-top:10px">${teamLeaderTable(teams,'y','YC')}</div></div><div class="card"><div class="eyebrow">RED CARDS · TEAM</div><div style="margin-top:10px">${teamLeaderTable(teams,'r','RC')}</div></div></div>`:''}<div class="muted" style="margin-top:10px;font-size:10px">${seasonFeed.assistsSource?`Assist source: ${esc(seasonFeed.assistsSource)} · `:''}${seasonFeed.updatedAt?`updated ${esc(seasonFeed.updatedAt)}`:''}</div>`}'''
text = text[:start] + new_render + text[end:]
part.write_text(text, encoding='utf-8')

validate = ROOT / 'scripts' / 'validate.py'
v = validate.read_text(encoding='utf-8')
old = "current_players = ((season_stats.get('seasons') or {}).get('2026/27') or {}).get('players') or []\nassert current_players, 'current-season player leaderboards are empty'"
new = "current_season_stats = ((season_stats.get('seasons') or {}).get('2026/27') or {})\ncurrent_players = current_season_stats.get('players') or []\ncurrent_assists = current_season_stats.get('assists') or []\nassert current_players, 'current-season goal leaderboard is empty'\nassert current_assists, 'current-season dedicated assist leaderboard is empty'\nassert 'asistencias-de-gol' in (current_season_stats.get('assistsSource') or ''), 'assist leaderboard is not using the dedicated assist-ranked source'\njavi = [p for p in current_assists if p.get('name') == 'Javi Hernández']\nassert javi and max(p.get('assists', 0) for p in javi) >= 2, f'Javi Hernández assist regression: {javi}'\nembedded_max = max((p.get('assistsInScorerFeed', 0) for p in current_players), default=0)\ndedicated_max = max((p.get('assists', 0) for p in current_assists), default=0)\nassert dedicated_max >= embedded_max, f'dedicated assist ranking below scorer-feed maximum: {dedicated_max} < {embedded_max}'"
if old not in v:
    raise SystemExit('validate season stats marker not found')
v = v.replace(old, new, 1)
validate.write_text(v, encoding='utf-8')
print('Patched Season Stats UI and validation for dedicated assists source')
